class Solution {
  public int minimumEffort(int[][] tasks) {
    java.util.Arrays.sort(tasks, (a, b) -> Integer.compare((b[1] - b[0]), (a[1] - a[0])));
    int energy = 0, current = 0;
    for (int[] t : tasks) {
      if (current < t[1]) {
        energy += t[1] - current;
        current = t[1];
      }
      current -= t[0];
    }
    return energy;
  }
}
